-- ============================================================
-- R10 (R-c): plan and timing on the PRODUCTION database, before vs after.
-- The only difference: the anti-req check is split into one NOT EXISTS
-- per side of the pair. Method from the project appendix: EXPLAIN,
-- 1 warm-up run, 5 timed runs, read the times from
-- performance_schema.events_statements_history. Report the median of the 5.
-- Run right after ./scripts/setup-db.sh:
--   mysql -u root -t -vvv < milestone-2/test-production-r10-timing.sql > milestone-2/test-production-r10-timing.out
-- The before query takes ~15-25 s per run, so this takes a few minutes.
-- ============================================================

USE CoursePlanner;

-- Refresh optimizer statistics after loading the data (as in the appendix)
ANALYZE TABLE Course, Prereq, Antireq, `User`, Checklist;

-- ---------- Before ----------
EXPLAIN SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;

-- 1 warm-up + 5 timed runs
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;
SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.status IN ('completed', 'in_progress') AND taken.course_id IN (a.course_id, a.antireq_course_id) WHERE c.course_id IN (a.course_id, a.antireq_course_id) AND taken.course_id != c.course_id) ORDER BY c.subject, c.catalog_number;

SELECT ROUND(TIMER_WAIT/1e9, 3) AS ms
FROM performance_schema.events_statements_history
WHERE SQL_TEXT LIKE 'SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c%'
ORDER BY EVENT_ID DESC LIMIT 5;

-- ---------- After (final query) ----------
EXPLAIN SELECT c.course_id, c.subject, c.catalog_number, c.title, c.units, c.min_term FROM Course c JOIN `User` u ON u.user_id = 1 WHERE (c.min_term IS NULL OR c.min_term <= u.next_study_term) AND NOT EXISTS (SELECT 1 FROM Prereq p WHERE p.course_id = c.course_id AND NOT EXISTS (SELECT 1 FROM Prereq alt JOIN Checklist done ON done.user_id = u.user_id AND done.course_id = alt.prereq_course_id AND done.status IN ('completed', 'in_progress') WHERE alt.course_id = p.course_id AND alt.alt_group = p.alt_group)) AND NOT EXISTS (SELECT 1 FROM Checklist mine WHERE mine.user_id = u.user_id AND mine.course_id = c.course_id AND mine.status IN ('completed', 'in_progress')) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.course_id = a.antireq_course_id AND taken.status IN ('completed', 'in_progress') WHERE a.course_id = c.course_id) AND NOT EXISTS (SELECT 1 FROM Antireq a JOIN Checklist taken ON taken.user_id = u.user_id AND taken.course_id = a.course_id AND taken.status IN ('completed', 'in_progress') WHERE a.antireq_course_id = c.course_id) ORDER BY c.subject, c.catalog_number;

